[tool error]
{
  "ok": false,
  "name": "station_to_xy",
  "error": {
    "type": "query_failed",
    "message": "no alignment named 'SR70'",
    "hint": "this document owns no alignments, but its references carry ['DESIGN:SR70'] -- name one of those to read its design"
  }
}

[tool error]
{
  "ok": false,
  "name": "draw_offset",
  "error": {
    "type": "invalid_params",
    "message": "Additional properties are not allowed ('space' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "offsets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": [
              "number",
              "string"
            ]
          },
          "description": "offset distances from the alignment, feet, right of the direction of stationing positive; a string may name the side ('12L', '12R'). A 24 ft pavement is [-12, 12]; add [-14, 14] for 2 ft shoulders."
        },
        "station_range": {
          "type": "array",
          "items": {
            "type": [
              "number",
              "string"
            ],
            "description": "display station: feet (1600) or '16+00.00'"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "draw only between these display stations: how a pavement edge stops at an intersection and picks up again on the far leg"
        },
        "layer": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "replace": {
          "type": "boolean",
          "description": "delete this alignment's previously drawn offsets at the same distances first (default false); with a station_range, only the pieces inside it"
        }
      },
      "required": [
        "offsets"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "offsets": [
        -12,
        12
      ],
      "layer": "rd_EP"
    }
  },
  "warnings": []
}

[tool error]
{
  "ok": false,
  "name": "draw_offset",
  "error": {
    "type": "command_failed",
    "message": "'DESIGN:SR70' is an alignment in an attached reference, and this command only works on this document's own design",
    "hint": "queries read a referenced design (station_to_xy, resolve_anchor, get_design_data, find_entities) and the labelers annotate one (place_label, annotate_stationing, place_curve_table, draw_station_offset, place_callout); to draw its linework, draw the base drawing itself",
    "example": {
      "alignment": "ALIGN-1",
      "offsets": [
        -12,
        12
      ],
      "layer": "rd_EP"
    }
  },
  "warnings": []
}

